-- CC_0306_hawaii_state_legislature.sql
-- Hawaii State Legislature — 2 chambers, 76 districts already loaded, 76 offices, 76 seated.
--
-- GENERATED by scripts/gen-hi-legislature-migration.mjs. Do not hand-edit; edit the generator.
-- Roster, sources, rulings and defects: backend/data/seed-hi-legislature-2026/ROSTERS.md
--
-- ═══ 🔴 HAWAII LEGISLATIVE TERMS BEGIN AND END ON GENERAL ELECTION DAY ═══
--
-- Constitution of the State of Hawaii, Article III, Section 4:
--
--   "The term of a member of the legislature shall begin on the day of the general election
--    at which elected ... For a member of the house of representatives, the terms shall end
--    on the day of the general election immediately following the day the member's term
--    commences."
--
-- NOT in January. On 2026-11-03 every one of the 51 House terms seated here ENDS and the
-- winners' terms begin the same day, as do 14 of the 25 Senate terms. This seed is correct
-- today and for six more days; the re-seat is an election-night operation, not a new year's one.
--
-- ═══ 🔴 TWO NAMES IN THIS ROSTER ALREADY EXIST IN PRODUCTION ON SOMEBODY ELSE ═══
--
-- This is why the people INSERT below is written per-row against an explicit allowlist
-- instead of the usual "insert where no active row matches (first_name, last_name)". That
-- guard would have silently skipped both of these and then seated the wrong person:
--
--   Mike Lee    — production's row (-400077) is the U.S. SENATOR FOR UTAH, Republican,
--                 photographed from the Congressional bioguide. Hawaii House District 50's
--                 Mike Lee is a different person. This is the documented "Mike Lee failure".
--   Chris Todd  — production's row (-4720073) is a TENNESSEE state representative, House
--                 District 73, photographed from wapp.capitol.tn.gov. Hawaii House District
--                 3's Chris Todd is a different person.
--
-- And two DO reuse an existing row, each confirmed by the person's own press coverage:
--
--   Brenton Awa (-150204)         "Republican state Sen. Brenton Awa ... has represented the
--                                 23rd district since 2022", GOP nominee for HI-02 in 2026.
--   Jarrett Keohokalole (-150103) "state Sen. Jarrett Keohokalole", HI-01 candidate who lost
--                                 the 2026 Democratic primary to Ed Case.
--
-- Both already exist as 2026 CONGRESSIONAL CANDIDATES, loaded 2026-07-07 from the HI Office
-- of Elections filing grid. Seeding them fresh would leave production with two of each: one
-- holding the Senate seat, one holding the candidacy.
--
-- ═══ DATES ═══
--
-- `office_terms.term_start` is the start of CONTINUOUS OCCUPANCY. The Legislature publishes
-- no service-start date for an elected member — only the current session — so the 72 elected
-- members get `start_precision = 'unknown'` with a NULL date, which is what Minnesota, South
-- Carolina and Mississippi carry for the same reason. "FIRST ELECTED IS NOT A TERM START".
--
-- ⚠ Hawaii is unusually DATABLE in principle, and that is a lead rather than a result: the
--   constitutional rule above fixes the day, so a member's start is computable from the
--   general election at which their continuous service began. Establishing that election for
--   72 people across several cycles is a research pass this seed does not make.
--
-- The four APPOINTEES are dated, because an appointment is an occupancy and the date is
-- published. Hawaii fills a legislative vacancy by gubernatorial appointment from three names
-- submitted by the departing member's party (Const. Art. III §5; HRS §17-3) — never by special
-- election — so a mid-term arrival here is always 'appointed'.
--
-- ═══ PARTY IS NOT WRITTEN ═══
--
-- These are partisan offices and the roster prints a party letter for every member, but
-- `politicians.party` stays NULL, which is what Minnesota, South Carolina and Florida carry
-- for their legislators (0 of 441 between them). Party lives on `races.primary_party`.

-- ── Pre-flight ────────────────────────────────────────────────────────────────
DO $$
DECLARE v_sldu int; v_sldl int; v_du int; v_dl int; v_ch int; v_reuse int; v_off int;
BEGIN
  SELECT count(*) INTO v_sldu FROM essentials.geofence_boundaries WHERE state='15' AND mtfcc='G5210';
  SELECT count(*) INTO v_sldl FROM essentials.geofence_boundaries WHERE state='15' AND mtfcc='G5220';
  IF v_sldu <> 25 OR v_sldl <> 51 THEN
    RAISE EXCEPTION 'CC_0306 pre-flight: expected 25/51 Hawaii SLDU/SLDL polygons, found %/% — run '
                    'scripts/load-state-tiger-boundaries.ts --state HI --fips 15 --layers sldu,sldl first. '
                    'An office on a district with no polygon is unreachable by any address and nothing errors.', v_sldu, v_sldl;
  END IF;

  SELECT count(*) INTO v_du FROM essentials.districts WHERE mtfcc='G5210' AND geo_id LIKE '15%' AND district_type='STATE_UPPER';
  SELECT count(*) INTO v_dl FROM essentials.districts WHERE mtfcc='G5220' AND geo_id LIKE '15%' AND district_type='STATE_LOWER';
  IF v_du <> 25 OR v_dl <> 51 THEN
    RAISE EXCEPTION 'CC_0306 pre-flight: expected 25/51 Hawaii state-leg district rows, found %/%', v_du, v_dl;
  END IF;

  SELECT count(*) INTO v_ch FROM essentials.chambers c JOIN essentials.governments g ON g.id=c.government_id
   WHERE g.name = 'State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives');
  IF v_ch <> 0 THEN
    RAISE EXCEPTION 'CC_0306 pre-flight: % Hawaii legislative chamber(s) already exist — read them first', v_ch;
  END IF;

  -- The two reused rows must still be the people the rulings identified.
  SELECT count(*) INTO v_reuse FROM essentials.politicians
   WHERE (external_id = -150204 AND full_name = 'Brenton Awa')
      OR (external_id = -150103 AND full_name = 'Jarrett Keohokalole');
  IF v_reuse <> 2 THEN
    RAISE EXCEPTION 'CC_0306 pre-flight: expected the 2 reusable rows (-150204 Awa, -150103 '
                    'Keohokalole), found % — re-read the identity rulings', v_reuse;
  END IF;

  -- 🔴 And the two LOOKALIKES must still be who they were, so a later reader can see that
  --    leaving them alone was deliberate rather than an oversight.
  SELECT count(*) INTO v_off FROM essentials.politicians p
    JOIN essentials.office_current_holder och ON och.politician_id = p.id
    JOIN essentials.offices o ON o.id = och.office_id
    JOIN essentials.chambers c ON c.id = o.chamber_id
    JOIN essentials.governments g ON g.id = c.government_id
   WHERE (p.external_id = -400077  AND g.name = 'United States Federal Government')
      OR (p.external_id = -4720073 AND g.name = 'State of Tennessee');
  IF v_off <> 2 THEN
    RAISE EXCEPTION 'CC_0306 pre-flight: the Mike Lee (-400077, US Senate Utah) and Chris Todd '
                    '(-4720073, Tennessee House) rows are not where the rulings left them (found %) '
                    '— re-check before inserting Hawaii people of the same names', v_off;
  END IF;
END $$;

-- ── Chambers ──────────────────────────────────────────────────────────────────
-- 🔴 `chambers.slug` is GENERATED ALWAYS from `name_formal`, NOT from `name`. Leaving
--    name_formal NULL silently generates an EMPTY slug, and the slug is what the app routes on.
INSERT INTO essentials.chambers
  (government_id, name, name_formal, official_count, term_length, staggered_term, election_rules, inauguration_rules, website_url)
SELECT g.id, v.name, v.name, v.n, v.len, v.stag, v.rules, v.inaug, v.url
FROM essentials.governments g
JOIN (VALUES
  ('Hawaii Senate', 25::bigint, '4', true,
   'Partisan. Four-year terms, staggered: 14 of the 25 seats were on the 2026 ballot and the rest run to 2028. '
   || 'A candidate nominated at the primary who is unopposed at the general is deemed elected at the primary '
   || '(Const. Art. III sec. 4).',
   'A term begins ON THE DAY OF THE GENERAL ELECTION at which the member is elected, not in January '
   || '(Const. Art. III sec. 4).',
   'https://www.capitol.hawaii.gov/legislature/legislators.aspx?chamber=S'),
  ('Hawaii House of Representatives', 51::bigint, '2', false,
   'Partisan. Two-year terms, so ALL 51 seats are on the ballot at every general election. '
   || 'A candidate nominated at the primary who is unopposed at the general is deemed elected at the primary '
   || '(Const. Art. III sec. 4).',
   'A term begins ON THE DAY OF THE GENERAL ELECTION at which the member is elected and ends on the day of '
   || 'the next general election (Const. Art. III sec. 4).',
   'https://www.capitol.hawaii.gov/legislature/legislators.aspx?chamber=H')
) AS v(name, n, len, stag, rules, inaug, url) ON true
WHERE g.name = 'State of Hawaii'
  AND NOT EXISTS (SELECT 1 FROM essentials.chambers c WHERE c.government_id = g.id AND c.name = v.name);

-- ── Offices ───────────────────────────────────────────────────────────────────
-- Title is the bare role; the district comes from districts.label. That is what Minnesota,
-- South Carolina, Florida and Mississippi all carry for their legislators.
INSERT INTO essentials.offices
  (chamber_id, district_id, title, representing_state, seats, is_vacant, voting_powers, partisan_type)
SELECT c.id, d.id, v.title, 'HI', 1, false, 'full', 'partisan'
FROM (VALUES ('G5210', 'STATE_UPPER', 'Hawaii Senate', 'Senator'),
             ('G5220', 'STATE_LOWER', 'Hawaii House of Representatives', 'Representative')) AS v(mtfcc, dtype, chamber, title)
JOIN essentials.districts d ON d.mtfcc = v.mtfcc AND d.district_type = v.dtype AND d.geo_id LIKE '15%'
JOIN essentials.governments g ON g.name = 'State of Hawaii'
JOIN essentials.chambers c ON c.government_id = g.id AND c.name = v.chamber
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.offices o WHERE o.district_id = d.id AND o.chamber_id = c.id AND o.title = v.title);

-- ── Roster ────────────────────────────────────────────────────────────────────
CREATE TEMP TABLE hi_leg(
  ch           text NOT NULL,
  district     int  NOT NULL,
  full_name    text NOT NULL,
  first_name   text NOT NULL,
  last_name    text NOT NULL,
  suffix       text,
  reuse_ext    bigint,
  term_start   date,
  precision    text NOT NULL,
  how_started  text NOT NULL,
  source       text NOT NULL,
  office_id     uuid,
  politician_id uuid,
  PRIMARY KEY (ch, district)
) ON COMMIT DROP;

