-- Resolve each roster row to its office.
UPDATE hi_leg r SET office_id = o.id
  FROM essentials.offices o
  JOIN essentials.districts d ON d.id = o.district_id
  JOIN essentials.chambers c ON c.id = o.chamber_id
  JOIN essentials.governments g ON g.id = c.government_id
 WHERE g.name = 'State of Hawaii'
   AND c.name = CASE r.ch WHEN 'S' THEN 'Hawaii Senate' ELSE 'Hawaii House of Representatives' END
   AND d.mtfcc = CASE r.ch WHEN 'S' THEN 'G5210' ELSE 'G5220' END
   AND d.geo_id = '15' || lpad(r.district::text, 3, '0');

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM hi_leg WHERE office_id IS NULL;
  IF n <> 0 THEN RAISE EXCEPTION 'CC_0306: % roster row(s) did not resolve to an office', n; END IF;
  SELECT count(*) INTO n FROM hi_leg r WHERE EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = r.office_id);
  IF n <> 0 THEN RAISE EXCEPTION 'CC_0306: % Hawaii legislative office(s) already carry a term', n; END IF;
END $$;

-- ── People ────────────────────────────────────────────────────────────────────
-- The two reuses first, BY EXTERNAL ID. Matching them by name would be the same unsafe
-- predicate that makes Mike Lee and Chris Todd dangerous.
UPDATE hi_leg r SET politician_id = p.id
  FROM essentials.politicians p WHERE p.external_id = r.reuse_ext AND r.reuse_ext IS NOT NULL;

-- 🔴 is_incumbent EXPLICITLY true. It defaults to false, and a seated person inserted
--    without it is HIDDEN from address search; check:occupancy fails an INSERT that omits it.
--    party stays NULL — see the header.
-- Pass 1 — the 72 with no name collision. THE DUPLICATE-NAME GUARD STAYS ARMED.
INSERT INTO essentials.politicians (full_name, first_name, last_name, name_suffix, is_active, is_incumbent, source)
SELECT r.full_name, r.first_name, r.last_name, r.suffix, true, true, r.source
  FROM hi_leg r WHERE r.politician_id IS NULL AND r.full_name NOT IN ('Mike Lee', 'Chris Todd');

-- Pass 2 — the TWO the guard is right to stop, lowered for exactly these rows and raised
-- again immediately. Production already holds a Mike Lee (the U.S. Senator for Utah) and a
-- Chris Todd (a Tennessee state representative); Hawaii's House District 50 and District 3
-- members are different people, verified against the offices those rows hold.
--
-- 🔴 The override is NOT set for the whole migration. 74 of the 76 inserts above and below
--    run with the guard live, because that guard is the only thing standing between this
--    seed and a second row for someone who is already here.
SET LOCAL essentials.allow_duplicate_name = 'on';
INSERT INTO essentials.politicians (full_name, first_name, last_name, name_suffix, is_active, is_incumbent, source)
SELECT r.full_name, r.first_name, r.last_name, r.suffix, true, true, r.source
  FROM hi_leg r WHERE r.politician_id IS NULL AND r.full_name IN ('Mike Lee', 'Chris Todd');
SET LOCAL essentials.allow_duplicate_name = 'off';

UPDATE hi_leg r SET politician_id = p.id
  FROM essentials.politicians p
 WHERE r.politician_id IS NULL AND p.full_name = r.full_name AND p.is_active
   AND p.source = r.source;

-- The two reused rows are standing candidates, so they were is_incumbent = false.
UPDATE essentials.politicians p SET is_incumbent = true, is_active = true
  FROM hi_leg r WHERE p.id = r.politician_id AND r.reuse_ext IS NOT NULL;

-- ── Seating ───────────────────────────────────────────────────────────────────
DO $$
DECLARE r record; n int := 0;
BEGIN
  FOR r IN SELECT * FROM hi_leg ORDER BY ch, district LOOP
    IF r.politician_id IS NULL THEN
      RAISE EXCEPTION 'CC_0306: % District % did not resolve to a person', r.ch, r.district;
    END IF;
    INSERT INTO essentials.office_terms
      (office_id, politician_id, term_start, start_precision, how_started, source)
    VALUES (r.office_id, r.politician_id, r.term_start, r.precision, r.how_started, r.source);
    n := n + 1;
  END LOOP;
  IF n <> 76 THEN RAISE EXCEPTION 'CC_0306: expected 76 seatings, got %', n; END IF;
END $$;

-- ── Post-verify gate ──────────────────────────────────────────────────────────
DO $$
DECLARE
  v_ch int; v_slug int; v_sen int; v_rep int; v_held int;
  v_appt int; v_elected int; v_unknown int; v_dated int;
  v_party int; v_notinc int; v_nogeom int; v_dupe int; v_lee int; v_todd int;
BEGIN
  SELECT count(*) INTO v_ch FROM essentials.chambers c JOIN essentials.governments g ON g.id=c.government_id
   WHERE g.name = 'State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives');
  IF v_ch <> 2 THEN RAISE EXCEPTION 'CC_0306 gate: expected 2 legislative chambers, found %', v_ch; END IF;

  SELECT count(*) INTO v_slug FROM essentials.chambers c JOIN essentials.governments g ON g.id=c.government_id
   WHERE g.name = 'State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives') AND (c.slug IS NULL OR btrim(c.slug) = '');
  IF v_slug <> 0 THEN RAISE EXCEPTION 'CC_0306 gate: % chamber(s) generated an EMPTY slug', v_slug; END IF;

  SELECT count(*) FILTER (WHERE c.name = 'Hawaii Senate'), count(*) FILTER (WHERE c.name = 'Hawaii House of Representatives')
    INTO v_sen, v_rep
    FROM essentials.offices o JOIN essentials.chambers c ON c.id=o.chamber_id
    JOIN essentials.governments g ON g.id=c.government_id WHERE g.name = 'State of Hawaii';
  IF v_sen <> 25 OR v_rep <> 51 THEN RAISE EXCEPTION 'CC_0306 gate: chamber sizes are %/25 senate, %/51 house', v_sen, v_rep; END IF;

  -- 🔴 Counted on och.politician_id: office_current_holder LEFT JOINs from offices, so a
  --    vacancy is a NULL politician_id that would pass a count(*) vacuously.
  SELECT count(och.politician_id) INTO v_held
    FROM essentials.offices o JOIN essentials.chambers c ON c.id=o.chamber_id
    JOIN essentials.governments g ON g.id=c.government_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE g.name = 'State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives');
  IF v_held <> 76 THEN RAISE EXCEPTION 'CC_0306 gate: expected 76 held legislative seats, found %', v_held; END IF;

  SELECT count(*) FILTER (WHERE t.how_started='appointed'), count(*) FILTER (WHERE t.how_started='elected'),
         count(*) FILTER (WHERE t.start_precision='unknown'), count(*) FILTER (WHERE t.term_start IS NOT NULL)
    INTO v_appt, v_elected, v_unknown, v_dated
    FROM essentials.office_terms t JOIN essentials.offices o ON o.id=t.office_id
    JOIN essentials.chambers c ON c.id=o.chamber_id JOIN essentials.governments g ON g.id=c.government_id
   WHERE g.name = 'State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives');
  IF v_appt <> 4 OR v_elected <> 72 OR v_unknown <> 72 OR v_dated <> 4 THEN
    RAISE EXCEPTION 'CC_0306 gate: expected 4 appointed / 72 elected / 72 unknown-precision / 4 dated, got %/%/%/%',
                    v_appt, v_elected, v_unknown, v_dated;
  END IF;

  SELECT count(*) INTO v_party FROM essentials.office_current_holder och
    JOIN essentials.offices o ON o.id=och.office_id JOIN essentials.chambers c ON c.id=o.chamber_id
    JOIN essentials.governments g ON g.id=c.government_id JOIN essentials.politicians p ON p.id=och.politician_id
   WHERE g.name = 'State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives') AND coalesce(btrim(p.party),'') <> '';
  IF v_party <> 0 THEN RAISE EXCEPTION 'CC_0306 gate: % legislator(s) carry a party; it belongs on races.primary_party', v_party; END IF;

  SELECT count(*) INTO v_notinc FROM essentials.office_current_holder och
    JOIN essentials.offices o ON o.id=och.office_id JOIN essentials.chambers c ON c.id=o.chamber_id
    JOIN essentials.governments g ON g.id=c.government_id JOIN essentials.politicians p ON p.id=och.politician_id
   WHERE g.name = 'State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives')
     AND (p.is_incumbent IS NOT TRUE OR p.is_active IS NOT TRUE);
  IF v_notinc <> 0 THEN RAISE EXCEPTION 'CC_0306 gate: % seated legislator(s) are not active incumbents and would be hidden from address search', v_notinc; END IF;

  SELECT count(*) INTO v_nogeom FROM essentials.offices o
    JOIN essentials.chambers c ON c.id=o.chamber_id JOIN essentials.governments g ON g.id=c.government_id
    JOIN essentials.districts d ON d.id=o.district_id
   WHERE g.name = 'State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives')
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries gb WHERE gb.geo_id=d.geo_id AND gb.mtfcc=d.mtfcc);
  IF v_nogeom <> 0 THEN RAISE EXCEPTION 'CC_0306 gate: % legislative office(s) sit on a district with no polygon', v_nogeom; END IF;

  -- One person per seat, and no person seated twice.
  SELECT count(*) INTO v_dupe FROM (
    SELECT och.politician_id FROM essentials.office_current_holder och
      JOIN essentials.offices o ON o.id=och.office_id JOIN essentials.chambers c ON c.id=o.chamber_id
      JOIN essentials.governments g ON g.id=c.government_id
     WHERE g.name = 'State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives') AND och.politician_id IS NOT NULL
     GROUP BY och.politician_id HAVING count(*) > 1) x;
  IF v_dupe <> 0 THEN RAISE EXCEPTION 'CC_0306 gate: % person(s) hold more than one legislative seat', v_dupe; END IF;

  -- 🔴 The lookalikes stayed where they were, and a Hawaii person of each name now exists.
  SELECT count(*) INTO v_lee FROM essentials.politicians WHERE full_name = 'Mike Lee' AND is_active;
  SELECT count(*) INTO v_todd FROM essentials.politicians WHERE full_name = 'Chris Todd' AND is_active;
  IF v_lee < 2 OR v_todd < 2 THEN
    RAISE EXCEPTION 'CC_0306 gate: expected a SECOND active Mike Lee and Chris Todd (the Hawaii ones) '
                    'alongside the Utah senator and the Tennessee representative, found % and % — '
                    'a name-based insert guard silently skipped them', v_lee, v_todd;
  END IF;

  RAISE NOTICE 'CC_0306 OK: 2 chambers, 76 offices, 76 seated (4 appointed, 2 reused rows).';
END $$;
